corrected_code:
package hr

import (
	"net/http"
	"github.com/golang-jwt/jwt/v5"
	"github.com/labstack/echo/v4"
	"myapp/reviews"
)

type CompReviewController struct {
	Store reviews.CompensationStore
}

func (ctrl *CompReviewController) DownloadCompensationReview(c echo.Context) error {
	reviewID := c.Param("reviewID")
	token := c.Get("user").(*jwt.Token)
	claims := token.Claims.(jwt.MapClaims)
	empID := claims["employee_id"].(string)
	isHR := claims["is_hr_admin"].(bool)

	doc, err := ctrl.Store.GetReviewDocumentForEmployee(c.Request().Context(), reviewID, empID, isHR)
	if err != nil {
		return c.JSON(http.StatusForbidden, echo.Map{"error": "Access denied to compensation record"})
	}

	return c.Blob(http.StatusOK, "application/pdf", doc)
}
